svg.script:
(function(){
  var BASE='https://cdn.jsdelivr.net/gh/purpleskulltrooper85-svg/geometry-dash-wasm@main/';
  var proxy=null;
  try{
    proxy=new URLSearchParams(location.search).get('proxy');
  }catch(e){}
  var inject=proxy
    ?('<script>try{localStorage.setItem("gdProxyBase",'
      +JSON.stringify(proxy)
      +')}catch(e){}<\/script>')
    :'';
  // cache-buster: jsDelivr branch URLs can serve stale copies for hours,
  // a unique query gives a fresh edge fetch every time
  fetch(BASE+'index.html?cb='+Date.now(),{cache:'no-store'})
    .then(function(r){return r.text();})
    .then(function(html){
      html=html.replace('<head>','<head><base href="'+BASE+'">'+inject);
      location.replace(URL.createObjectURL(new Blob([html],{type:'text/html'})));
    })
    .catch(function(){
      location.replace(BASE+'index.html');
    });
})();
